<template><view class="page"><view class="eyebrow">训练与复盘</view><view class="page-title">短练习，强反馈</view><view class="hero"><view class="hero-kicker">今日推荐 · 概括题</view><view class="hero-title">找准要点，写出层次</view><view class="hero-desc">从今日材料开始，提交后按规则定位主要失分点。</view><view class="hero-action" @tap="startToday">进入今日训练</view></view><view class="section-head"><view class="section-title">最近训练</view><view class="section-meta">{{ drills.length }} 条</view></view><view v-if="loading" class="card state-card">正在读取训练记录…</view><view v-else-if="!drills.length" class="card state-card">完成今日任务后，规则反馈会沉淀在这里。</view><view v-for="item in drills" :key="item.id" class="card drill-card"><view class="card-title">{{ item.prompt || '申论短作答' }}</view><view class="drill-content">{{ item.content }}</view><view class="card-desc">{{ formatDate(item.createdAt) }}</view></view><view class="section-head"><view class="section-title">能力模块</view></view><view v-for="item in items" :key="item" class="card row"><view class="step">练</view><view><view class="card-title">{{ item }}</view><view class="card-desc">分题型深练将按内容审核进度逐步开放</view></view><view class="tag">规划中</view></view></view></template>
<script setup lang="ts">import { ref } from 'vue';import Taro,{useDidShow} from '@tarojs/taro';import {api,type ShenlunDrill} from '@/api';import {useDailyTaskStore} from '@/store/dailyTask';import {isLoggedIn} from '@/utils/auth';import {showToast} from '@/utils/platform';const items=['归纳概括','综合分析','提出对策','贯彻执行','文章写作'];const drills=ref<ShenlunDrill[]>([]);const loading=ref(false);const store=useDailyTaskStore();async function load(){if(!isLoggedIn())return;loading.value=true;const response=await api.listDrills();loading.value=false;if(response.code===0&&response.data)drills.value=response.data;else showToast(response.message||'训练记录加载失败')}async function startToday(){if(!isLoggedIn())return Taro.navigateTo({url:'/pages/auth/login'});await store.load();if(!store.task)return showToast(store.message||'今日任务尚未准备好');const task=store.task;if(task.progress.state==='completed')return Taro.switchTab({url:'/pages/today/index'});if(task.progress.state==='not_started'&&!await store.start())return showToast(store.message||'任务启动失败');Taro.navigateTo({url:`/pages/reading/detail?id=${task.contentId}&taskId=${task.id}`})}function formatDate(value:string){return value?value.slice(0,16).replace('T',' '):''}useDidShow(()=>void load())</script>
